      "details": "درس يتناول نصوصاً قرآنية كريمة تؤسس لمنظومة القيم الإنسانية والأخلاقية التي تهدف إلى تهذيب السلوك وبناء مجتمع قائم على العدل والتكافل والتوازن، مع التركيز على مهارات الفهم والتحليل والتذوق البلاغي.",
