      "الأعداد المركبة (11-19) تميز بمفرد منصوب، وتُبنى على فتح الجزأين عدا (12) الذي يُعرب جزؤه الأول إعراب المثنى.",
      "ألفاظ العقود (20-90) تلزم حالة واحدة وتُلحق بجمع المذكر السالم في الإعراب، وتمييزها مفرد منصوب.",
      "الأعداد (مئة، ألف، مليون، مليار) تلزم صيغة واحدة مع المذكر والمؤنث، وتُعرب حسب موقعها، ومعدودها مفرد مضاف إليه مجرور.",
      "عند كتابة الأعداد بعد لفظي \"عام\" و\"سنة\"، يُراعى جر العدد الأول بالإضافة (ألفِ) وعطف ما بعده مجروراً مع تطبيق قواعد المخالفة والمطابقة."
